export const getRemoveSavedProjectUrl = (projectId: string,) => {




  return `/api/saved-projects/${projectId}`
}

/**
 * @summary Remove a saved project idea
 */
export const removeSavedProject = async (projectId: string, options?: Parameters<typeof customFetch>[1]): Promise<MutationStatus> => {

  return customFetch<MutationStatus>(getRemoveSavedProjectUrl(projectId),
  {
    ...options,
    method: 'DELETE'


  }
);}





export const getRemoveSavedProjectMutationKey = () => ['removeSavedProject'] as const;

export const getRemoveSavedProjectMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof removeSavedProject>>, TError,RemoveSavedProjectMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof removeSavedProject>>, TError,RemoveSavedProjectMutationVariables, TContext> => {

const mutationKey = getRemoveSavedProjectMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof removeSavedProject>>, RemoveSavedProjectMutationVariables> = (props) => {
          const {projectId} = props ?? {};

          return  removeSavedProject(projectId,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RemoveSavedProjectMutationResult = NonNullable<Awaited<ReturnType<typeof removeSavedProject>>>

    export type RemoveSavedProjectMutationError = ErrorType<unknown>
    export type RemoveSavedProjectMutationVariables = {projectId: string}

    /**
 * @summary Remove a saved project idea
 */
export const useRemoveSavedProject = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof removeSavedProject>>, TError,RemoveSavedProjectMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof removeSavedProject>>,
        TError,
        RemoveSavedProjectMutationVariables,
        TContext
      > => {
      return useMutation(getRemoveSavedProjectMutationOptions(options));
    }

export const getGetInternshipsUrl = () => {




  return `/api/internships`
}

/**
 * @summary List sample internship opportunities
 */
export const getInternships = async ( options?: Parameters<typeof customFetch>[1]): Promise<Internship[]> => {

  return customFetch<Internship[]>(getGetInternshipsUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetInternshipsQueryKey = () => {
    return [
    `/api/internships`
    ] as const;
    }


export const getGetInternshipsQueryOptions = <TData = Awaited<ReturnType<typeof getInternships>>, TError = ErrorType<unknown>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getInternships>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetInternshipsQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getInternships>>> = ({ signal }) => getInternships({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getInternships>>, TError, TData> & { queryKey: QueryKey }
}

export type GetInternshipsQueryResult = NonNullable<Awaited<ReturnType<typeof getInternships>>>
export type GetInternshipsQueryError = ErrorType<unknown>


/**
 * @summary List sample internship opportunities
 */

export function useGetInternships<TData = Awaited<ReturnType<typeof getInternships>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getInternships>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetInternshipsQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







